export const DEFAULT_PYTHON_CODE = `"""
MAZE RUNNER - Autonomous Maze-Solving Controller
------------------------------------------------
Environment Context:
- MAZE_DATA: Global dictionary with environment info:
    - MAZE_DATA["width"]: grid width (nodes in x)
    - MAZE_DATA["height"]: grid height (nodes in y)
    - MAZE_DATA["start_node"]: [x, y] coordinates
    - MAZE_DATA["end_node"]: [x, y] coordinates
    - MAZE_DATA["grid"]: 2D array [height][width] of bitwise walls:
        1 = NORTH wall (y - 1)
        2 = EAST wall  (x + 1)
        4 = SOUTH wall (y + 1)
        8 = WEST wall  (x - 1)

Objective:
- Implement solve() returning an array of sequential motor commands:
  Valid commands: 'FORWARD', 'LEFT', 'RIGHT', 'U_TURN'
- Starting position: MAZE_DATA["start_node"] facing 'E' (East).
"""

from collections import deque

WALL_NORTH = 1
WALL_EAST  = 2
WALL_SOUTH = 4
WALL_WEST  = 8

DIRECTIONS = ['N', 'E', 'S', 'W']
DIR_OFFSETS = {
    'N': (0, -1, WALL_NORTH),
    'E': (1, 0, WALL_EAST),
    'S': (0, 1, WALL_SOUTH),
    'W': (-1, 0, WALL_WEST)
}

def solve():
    print(f"Solving maze: Start {MAZE_DATA['start_node']} -> Target {MAZE_DATA['end_node']}")
    width = MAZE_DATA["width"]
    height = MAZE_DATA["height"]
    start = tuple(MAZE_DATA["start_node"])
    target = tuple(MAZE_DATA["end_node"])
    grid = MAZE_DATA["grid"]

    # Shortest path search with state (x, y, heading)
    queue = deque([(start[0], start[1], 'E', [])])
    visited = set([(start[0], start[1], 'E')])

    while queue:
        x, y, heading, path = queue.popleft()
        
        if (x, y) == target:
            print(f"Found path with {len(path)} commands!")
            return path
            
        cur_walls = grid[y][x]
        
        # 1. Forward move
        dx, dy, wall_mask = DIR_OFFSETS[heading]
        nx, ny = x + dx, y + dy
        if not (cur_walls & wall_mask) and 0 <= nx < width and 0 <= ny < height:
            state = (nx, ny, heading)
            if state not in visited:
                visited.add(state)
                queue.append((nx, ny, heading, path + ['FORWARD']))

        # 2. Turn Left
        left_heading = DIRECTIONS[(DIRECTIONS.index(heading) - 1) % 4]
        state = (x, y, left_heading)
        if state not in visited:
            visited.add(state)
            queue.append((x, y, left_heading, path + ['LEFT']))

        # 3. Turn Right
        right_heading = DIRECTIONS[(DIRECTIONS.index(heading) + 1) % 4]
        state = (x, y, right_heading)
        if state not in visited:
            visited.add(state)
            queue.append((x, y, right_heading, path + ['RIGHT']))

    print("No valid path found to target!")
    return []
`;
