'use client';

import React, { useState } from 'react';
import Editor from '@monaco-editor/react';
import { Play, RotateCcw, Square, Code2, Sparkles, Loader2 } from 'lucide-react';
import ConsoleOutput from './ConsoleOutput';
import { LogEntry } from '../types/maze';
import { DEFAULT_PYTHON_CODE } from '../utils/defaultPythonCode';

interface CodePanelProps {
  pythonCode: string;
  onCodeChange: (code: string) => void;
  onRunSimulation: () => void;
  onStopSimulation: () => void;
  isExecutingCode: boolean;
  isSimulating: boolean;
  logs: LogEntry[];
  onClearLogs: () => void;
}

export default function CodePanel({
  pythonCode,
  onCodeChange,
  onRunSimulation,
  onStopSimulation,
  isExecutingCode,
  isSimulating,
  logs,
  onClearLogs,
}: CodePanelProps) {
  const [editorTheme] = useState('vs-dark');

  const handleResetToDefault = () => {
    if (confirm('Reset your Python editor to the default template?')) {
      onCodeChange(DEFAULT_PYTHON_CODE);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#111827] border border-slate-800 rounded-xl overflow-hidden shadow-2xl">
      {/* Editor Header */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-slate-900 border-b border-slate-800">
        <div className="flex items-center gap-2">
          <div className="p-1 rounded bg-amber-500/10 text-amber-400">
            <Code2 className="w-4 h-4" />
          </div>
          <span className="font-semibold text-slate-200 text-sm">solver.py</span>
          <span className="text-xs text-slate-500 font-mono">(Python 3 / Pyodide WASM)</span>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={handleResetToDefault}
            title="Reset code to default template"
            className="flex items-center gap-1 px-2.5 py-1 text-xs text-slate-400 hover:text-slate-200 hover:bg-slate-800 rounded-md transition-colors"
          >
            <RotateCcw className="w-3.5 h-3.5" />
            <span>Reset Template</span>
          </button>
        </div>
      </div>

      {/* Monaco Editor Container */}
      <div className="flex-1 min-h-[300px] relative">
        <Editor
          height="100%"
          language="python"
          theme={editorTheme}
          value={pythonCode}
          onChange={(val) => onCodeChange(val || '')}
          options={{
            minimap: { enabled: false },
            fontSize: 13,
            lineNumbers: 'on',
            scrollBeyondLastLine: false,
            automaticLayout: true,
            tabSize: 4,
            wordWrap: 'on',
            fontFamily: 'Fira Code, JetBrains Mono, Menlo, Monaco, Consolas, monospace',
            padding: { top: 12, bottom: 12 },
            renderLineHighlight: 'all',
          }}
          loading={
            <div className="flex items-center justify-center h-full text-slate-400 text-sm gap-2">
              <Loader2 className="w-4 h-4 animate-spin text-cyan-400" />
              <span>Loading Monaco Editor...</span>
            </div>
          }
        />
      </div>

      {/* Execution Action Bar */}
      <div className="p-3 bg-slate-900/90 border-t border-slate-800 flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          {!isSimulating ? (
            <button
              onClick={onRunSimulation}
              disabled={isExecutingCode}
              className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white font-medium text-sm shadow-lg shadow-emerald-500/20 active:scale-98 transition-all disabled:opacity-50 cursor-pointer"
            >
              {isExecutingCode ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Solving with Pyodide...</span>
                </>
              ) : (
                <>
                  <Play className="w-4 h-4 fill-white" />
                  <span>Run Simulation</span>
                </>
              )}
            </button>
          ) : (
            <button
              onClick={onStopSimulation}
              className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-rose-600 hover:bg-rose-500 text-white font-medium text-sm shadow-lg shadow-rose-600/30 active:scale-98 transition-all cursor-pointer"
            >
              <Square className="w-4 h-4 fill-white" />
              <span>Stop Simulation</span>
            </button>
          )}
        </div>

        <div className="flex items-center gap-2 text-xs text-slate-400">
          <Sparkles className="w-3.5 h-3.5 text-cyan-400" />
          <span>WASM Sandbox</span>
        </div>
      </div>

      {/* Console Output Subpanel */}
      <div className="p-3 pt-0 bg-slate-900/90">
        <ConsoleOutput logs={logs} onClearLogs={onClearLogs} />
      </div>
    </div>
  );
}
